package stream

import (
	"encoding/json"
	"strings"
	"testing"
)

// TestDescribeHonesty is the spec floor for the descriptor honesty projection
// (tv-playback-unblock "Playback descriptor and verb split", MODIFIED delta;
// design D1/D2/D3): a non-native direct floor answers state preparing (a pack
// can land) or unsupported (packaging cannot help) with an additive
// state_reason projected from STORED ffprobe facts only — the play URL stays
// (D2), hls answers and native-container answers keep the classic shape, the
// persisted document is never written, and the persisted packaging namespace
// never carries the projection.
func TestDescribeHonesty(t *testing.T) {
	// Synthetic verbatim ffprobe blobs (the same fixture shapes
	// TestClassification judges).
	const (
		mkvPackable = `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`
		mkvOptIn    = `{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`
		mkvTenBit   = `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`
		mp4Native   = `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`
	)
	facts := func(raw string) map[string]any {
		t.Helper()
		var f map[string]any
		if err := json.Unmarshal([]byte(raw), &f); err != nil {
			t.Fatalf("unmarshal ffprobe fixture: %v", err)
		}
		return f
	}

	cases := []struct {
		name           string
		optIn          bool // the Service's opt-in codec knob
		doc            map[string]any
		wantMode       string
		wantState      string
		wantReason     string
		wantFloorURL   bool // play_url is the direct floor's original URL
		wantPlaylistHR bool // play_url rides the stored playlist (hls)
	}{
		// Scenario: non-native container answers preparing with a reason.
		{
			name:         "unpackaged_mkv_packable_answers_preparing",
			doc:          map[string]any{"ffprobe": facts(mkvPackable)},
			wantMode:     ModeDirect,
			wantState:    StatePreparing,
			wantReason:   ReasonNonNativeContainer,
			wantFloorURL: true,
		},
		// Scenario: packaging-hopeless codec answers unsupported until the
		// knob flips — opt_in classification knob-off is codec_not_opted_in.
		{
			name:         "mkv_opt_in_knob_off_answers_unsupported_not_opted_in",
			doc:          map[string]any{"ffprobe": facts(mkvOptIn)},
			wantMode:     ModeDirect,
			wantState:    StateUnsupported,
			wantReason:   ReasonCodecNotOptedIn,
			wantFloorURL: true,
		},
		{
			name:         "mkv_opt_in_knob_on_answers_preparing",
			optIn:        true,
			doc:          map[string]any{"ffprobe": facts(mkvOptIn)},
			wantMode:     ModeDirect,
			wantState:    StatePreparing,
			wantReason:   ReasonNonNativeContainer,
			wantFloorURL: true,
		},
		// direct_only is unsupported regardless of the knob.
		{
			name:         "mkv_direct_only_answers_unsupported_codec",
			optIn:        true,
			doc:          map[string]any{"ffprobe": facts(mkvTenBit)},
			wantMode:     ModeDirect,
			wantState:    StateUnsupported,
			wantReason:   ReasonCodecUnsupported,
			wantFloorURL: true,
		},
		// Scenario: native container keeps the classic descriptor — state as
		// persisted, no reason, playable play URL.
		{
			name:         "unpackaged_mp4_keeps_classic_descriptor",
			doc:          map[string]any{"ffprobe": facts(mp4Native)},
			wantMode:     ModeDirect,
			wantState:    StateNone,
			wantReason:   "",
			wantFloorURL: true,
		},
		// Packaged answers unchanged (hls, no reason) even over non-native
		// source facts.
		{
			name: "packaged_partial_answers_unchanged",
			doc: map[string]any{
				"streams": map[string]any{"state": StatePartial, "playlist": "/media/it/n0/index.m3u8"},
				"ffprobe": facts(mkvPackable),
			},
			wantMode:       ModeHls,
			wantState:      StatePartial,
			wantReason:     "",
			wantPlaylistHR: true,
		},
		// Scenario: broken build answers the direct floor — and the D5 guard's
		// wire shape is byte-identical: persisted state, no projection.
		{
			name: "broken_build_answers_persisted_state_without_reason",
			doc: func() map[string]any {
				d := completeDoc("it", "n1") // no build on disk (fresh Root below)
				d["ffprobe"] = facts(mkvPackable)
				return d
			}(),
			wantMode:     ModeDirect,
			wantState:    StateComplete,
			wantReason:   "",
			wantFloorURL: true,
		},
		// A failed state keeps its value and retry affordance, carrying only
		// the non-native marker.
		{
			name: "failed_non_native_keeps_state_with_marker",
			doc: map[string]any{
				"streams": map[string]any{"state": StateFailed, "reason": "ffmpeg died"},
				"ffprobe": facts(mkvPackable),
			},
			wantMode:     ModeDirect,
			wantState:    StateFailed,
			wantReason:   ReasonNonNativeContainer,
			wantFloorURL: true,
		},
		{
			name: "failed_native_carries_no_reason",
			doc: map[string]any{
				"streams": map[string]any{"state": StateFailed, "reason": "ffmpeg died"},
				"ffprobe": facts(mp4Native),
			},
			wantMode:     ModeDirect,
			wantState:    StateFailed,
			wantReason:   "",
			wantFloorURL: true,
		},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			s := &Service{Secret: []byte("k"), OptInCodecs: tc.optIn, Root: t.TempDir()}
			mode, state, playURL, _, _, reason := s.Describe("it", tc.doc)
			if mode != tc.wantMode || state != tc.wantState {
				t.Fatalf("mode/state = %q/%q, want %q/%q", mode, state, tc.wantMode, tc.wantState)
			}
			if reason != tc.wantReason {
				t.Fatalf("state_reason = %q, want %q", reason, tc.wantReason)
			}
			// D2: the play URL is retained on every answer — the floor's own
			// address on direct answers, the stored playlist on hls ones.
			switch {
			case tc.wantFloorURL:
				if !strings.HasPrefix(playURL, mediaPrefix+"/it/original?"+tokenQuery+"=") {
					t.Fatalf("playURL = %q, want the retained direct floor URL", playURL)
				}
			case tc.wantPlaylistHR:
				if !strings.HasPrefix(playURL, "/media/it/n0/index.m3u8?"+tokenQuery+"=") {
					t.Fatalf("playURL = %q, want the stored playlist URL", playURL)
				}
			}
		})
	}

	t.Run("persisted_doc_never_written", func(t *testing.T) {
		// The projection is read-side only: the descriptor of a preparing
		// floor must leave the stored document byte-identical.
		s := &Service{Secret: []byte("k")}
		d := map[string]any{
			"streams": map[string]any{"state": StateNone},
			"ffprobe": facts(mkvPackable),
		}
		before, err := json.Marshal(d)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		mode, state, _, _, _, reason := s.Describe("it", d)
		if mode != ModeDirect || state != StatePreparing || reason != ReasonNonNativeContainer {
			t.Fatalf("descriptor = %q/%q/%q, want the preparing projection", mode, state, reason)
		}
		after, err := json.Marshal(d)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		if string(before) != string(after) {
			t.Fatalf("Describe mutated the document:\nbefore %s\nafter  %s", before, after)
		}
	})
}
